"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["62071"],{71287(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formulario_processo.fase_incoerente_com_finalidade","status":422,"titulo":"A fase do formul\xe1rio n\xe3o \xe9 a que a finalidade pede"},"descricao":{"codigo":"uniplus.selecao.formulario_processo.fase_incoerente_com_finalidade","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["Cada formul\xe1rio do processo tem uma finalidade (inscri\xe7\xe3o, pedido de isen\xe7\xe3o da\\ntaxa ou habilita\xe7\xe3o), e a fase em que ele \xe9 respondido tem de ser uma fase do\\ncronograma que atende essa finalidade. Hoje a regra \xe9 esta:","- o formul\xe1rio de **inscri\xe7\xe3o** se responde na fase que coleta a inscri\xe7\xe3o;\\n- o formul\xe1rio de **isen\xe7\xe3o da taxa**, na fase que abre o pedido de isen\xe7\xe3o;\\n- o formul\xe1rio de **habilita\xe7\xe3o**, na fase cujo c\xf3digo \xe9 `HABILITACAO`.","Inscri\xe7\xe3o e isen\xe7\xe3o podem dividir a mesma fase. A fase indicada para o formul\xe1rio\\nexiste no cronograma, mas n\xe3o atende a finalidade dele; a mensagem diz o c\xf3digo\\nda fase e a finalidade.","A recusa sai em duas ocasi\xf5es. Na grava\xe7\xe3o do formul\xe1rio\\n(`PUT .../formularios/{finalidade}` com `faseId`), vem em `faseId` e soma-se, no\\narray `errors[]`, \xe0s recusas das etapas do mesmo formul\xe1rio (a fase que n\xe3o\\nconsta do cronograma sai com\\n[`fase_fora_do_cronograma`](/erros/uniplus.selecao.formulario_processo.fase_fora_do_cronograma)).\\nNa publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, \xe9\\numa pend\xeancia da configura\xe7\xe3o, conferida na mesma ordem dos dois caminhos: se a\\nfase de algum formul\xe1rio n\xe3o atende a finalidade, a primeira pend\xeancia decide o\\nc\xf3digo devolvido. Isso pode acontecer tamb\xe9m depois da grava\xe7\xe3o, se a fase do\\ncronograma deixa de coletar a inscri\xe7\xe3o ou o pedido de isen\xe7\xe3o."],"comoResolver":["Ligue o formul\xe1rio \xe0 fase do cronograma que atende a finalidade dele, regravando\\no formul\xe1rio com o `faseId` dessa fase. Se o cronograma n\xe3o tem a fase certa\\n(a que coleta a inscri\xe7\xe3o, a que abre o pedido de isen\xe7\xe3o ou a de habilita\xe7\xe3o),\\ninclua-a pela defini\xe7\xe3o do cronograma de fases e depois grave o formul\xe1rio. Na\\npublica\xe7\xe3o, regrave o formul\xe1rio e repita a opera\xe7\xe3o. Na retifica\xe7\xe3o em ato\\n\xfanico, o pedido n\xe3o traz o formul\xe1rio, e a recusa indica que a configura\xe7\xe3o\\npublicada divergiu da finalidade: a equipe t\xe9cnica do Uni+ deve investigar."],"ondeAparece":["Grava\xe7\xe3o do formul\xe1rio do processo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formulario processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);